use serde_json::json;
use std::time::Instant;
#[tokio::main]
async fn main(){
 let dir=std::env::temp_dir().join(format!("neura-store-burst-{}",uuid::Uuid::new_v4()));
 std::fs::create_dir(&dir).unwrap();
 let(e,_)=tokio::sync::broadcast::channel(8);
 let s=store_check::store::StoreHandle::open(&dir.join("store.sqlite"),e).await.unwrap();
 for round in 0..5 {
 let start=Instant::now();let mut set=tokio::task::JoinSet::new();
 let gate=std::sync::Arc::new(tokio::sync::Barrier::new(33));
 for i in 0..32 {let s=s.clone();let gate=gate.clone();set.spawn(async move{
 gate.wait().await;let t=Instant::now();let id=format!("{round}-{i}");
 s.call("operation_start",json!({"id":id,"hash":"h"})).await.unwrap();
 s.call("operation_finish",json!({"id":id,"status":"done","result":"{}"})).await.unwrap();
 t.elapsed().as_secs_f64()*1000.
 });}
 gate.wait().await;let mut ms=Vec::new();while let Some(r)=set.join_next().await{ms.push(r.unwrap());}
 ms.sort_by(f64::total_cmp);
 println!("{}",json!({"round":round,"p50Ms":ms[16],"maxMs":ms[31],"elapsedMs":start.elapsed().as_secs_f64()*1000.}));
 }
}
